import{_ as s,o as n,a as p,b as c}from"./app.BGziXukh.js";const l="/ascendc.github.io/assets/aicore_31.DCg0CA0H.png",e="/ascendc.github.io/assets/aicore_32.C6mcU0Ip.png",S=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"概念原理和术语","link":"/guide/technical_appendix/concepts_and_terms/concepts_and_terms"},{"text":"内存访问原理","link":"/guide/technical_appendix/concepts_and_terms/memory_access/memory_access"},{"text":"Scalar读写数据","link":"/guide/technical_appendix/concepts_and_terms/memory_access/scalar_read_write"}]},"headers":[],"relativePath":"guide/technical_appendix/concepts_and_terms/memory_access/scalar_read_write.md","filePath":"guide/technical_appendix/concepts_and_terms/memory_access/scalar_read_write.md","outlineHeaders":[{"level":2,"title":"Scalar读写Global Memory","slug":"Scalar读写Global-Memory","link":"#Scalar读写Global-Memory"},{"level":2,"title":"Scalar读写UB","slug":"Scalar读写UB","link":"#Scalar读写UB"},{"level":2,"title":"Scalar读写数据时的同步","slug":"Scalar读写数据时的同步","link":"#Scalar读写数据时的同步"}],"lastUpdated":1794895320000}'),t={name:"guide/technical_appendix/concepts_and_terms/memory_access/scalar_read_write.md"};function d(o,a,r,i,h,_){return n(),p("div",null,[...a[0]||(a[0]=[c('<div><article class="markdown-body"><h1>Scalar读写数据<span id="ZH-CN_TOPIC_0000002375401226"></span></h1><p>AI Core中Scalar计算单元负责各类型的标量数据运算和程序的流程控制。根据<a href="../../../programming_guide/advanced_programming/hardware_implementation/basic_architecture.html">硬件架构</a>设计，Scalar仅支持对Global Memory和Unified Buffer（UB）的读写操作，而不支持对L1 Buffer、L0A Buffer、L0B Buffer和L0C Buffer等其他类型存储的访问。下文分别介绍了Scalar读写Global Memory和UB的方式和Scalar读写数据时的同步机制。</p><h2 id="Scalar读写Global-Memory">Scalar读写Global Memory<span id="section7480536235"></span><a class="header-anchor" href="#Scalar读写Global-Memory">​</a></h2><img src="'+l+`" alt width="600px" height="475px"><p>如上图所示，Scalar读写GM数据时会经过DataCache，DataCache主要用于提高标量访存指令的执行效率，每一个AIC/AIV核内均有一个独立的DataCache。下面通过一个具体示例来讲解DataCache的具体工作机制。</p><p>globalTensor1是位于GM上的Tensor：</p><ul><li>执行完GetValue(0)后，globalTensor1的前8个元素会进入DataCache，后续GetValue(1)~GetValue(7)不需要再访问GM，而可以直接从DataCache的Cache Line中读取数据，提高了标量连续访问的效率。</li><li>执行完SetValue(8, val)后，globalTensor1的index为8~15的元素会进入DataCache，SetValue只会修改DataCache中的Cache Line数据，同时将Cache Line的状态设置为Dirty，表明Cache Line中的数据与GM中的数据不一致。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">int64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">globalTensor1</span><span class="p">;</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">input</span><span class="p">);</span>
<span class="c1">// 从0~7共计8个uint64_t类型，DataCache的Cache Line长度为64字节</span>
<span class="c1">// 执行完GetValue(0)后，GetValue(1)~GetValue(7)可以直接从Cache Line中读取，不需要再访问GM</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">3</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">4</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">5</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">6</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">7</span><span class="p">);</span>

<span class="c1">// 执行完SetValue(8)后，不会修改GM上的数据，只会修改DataCache中Cache Line数据</span>
<span class="c1">// 同时Cache Line的状态置为dirty，dirty表示DataCache中Cache Line数据与GM中的数据不一致</span>
<span class="kt">int64_t</span><span class="w"> </span><span class="n">val</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="n">val</span><span class="p">);</span>
<span class="n">globalTensor1</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">8</span><span class="p">);</span>
</code></pre></div><p>根据上文的工作机制（如下图所示），多核间访问globalTensor1会出现数据不一致的情况，如果其余核需要获取GM数据的变化，则需要开发者手动调用<a href="../../../../api/SIMD-API/basic_api/cache_control/DataCacheCleanAndInvalid.html">DataCacheCleanAndInvalid</a>来保证数据的一致性。</p><img src="`+e+`" alt width="600px" height="269px"><h2 id="Scalar读写UB">Scalar读写UB<span id="section8156161471119"></span><a class="header-anchor" href="#Scalar读写UB">​</a></h2><p>Scalar读写UB时，可以使用LocalTensor的SetValue和GetValue接口。示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">inputLocal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">i</span><span class="p">);</span><span class="w"> </span><span class="c1">// 对inputLocal中第i个位置进行赋值为i</span>
<span class="p">}</span>

<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">srcLen</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">element</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">inputLocal</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="n">i</span><span class="p">);</span><span class="w"> </span><span class="c1">// 获取inputLocal中第i个位置的数值</span>
<span class="p">}</span>
</code></pre></div><h2 id="Scalar读写数据时的同步">Scalar读写数据时的同步<span id="section554364118119"></span><a class="header-anchor" href="#Scalar读写数据时的同步">​</a></h2><p>Scalar读写Global Memory和UB时属于PIPE_S（Scalar流水）操作，当用户使用SetValue或者GetValue接口，且算子工程开启自动同步时，不需要手动插入同步事件。</p><p>如果用户关闭算子工程的自动同步功能时，需要根据依赖对象判断是否插入同步事件。需要区分以下两类依赖：</p><ul><li>如果后续指令只使用<code>GetValue</code>返回的标量值作为入参，此时后续流水依赖的是Scalar流水产生的标量值。Scalar流水会在该标量值就绪后发射后续指令，后续指令不需要再从UB或GM读取该标量值，因此不需要额外插入<code>S_V</code>同步。</li><li>如果后续流水需要读取<code>SetValue</code>写入的UB或GM数据，依赖的是Scalar对存储位置的写入结果，必须通过对应的同步事件保证数据已写入后再读取。其他流水对UB或GM存在真实读写依赖时，也仍需保留相应同步。</li></ul><p>常见流水依赖和同步方式如下。表中的“依赖对象”指后续流水真正需要等待的内容；如果后续指令只接收Scalar流水产生的标量值，不需要等待Scalar对存储地址的写入，则不插入额外同步。</p><table><thead><tr><th>生产者流水</th><th>消费者流水</th><th>Scalar操作</th><th>依赖对象</th><th>同步方式</th><th>说明</th></tr></thead><tbody><tr><td>MTE2</td><td>Scalar</td><td><code>GetValue</code>/<code>SetValue</code></td><td>UB数据</td><td><code>MTE2_S</code></td><td><code>DataCopy</code>从GM搬入UB后，Scalar读取或修改该UB地址。</td></tr><tr><td>Vector</td><td>Scalar</td><td><code>GetValue</code>/<code>SetValue</code></td><td>UB数据</td><td><code>V_S</code></td><td>Vector写入UB后，Scalar读取或修改该UB地址。</td></tr><tr><td>MTE3</td><td>Scalar</td><td><code>GetValue</code>/<code>SetValue</code></td><td>GM数据</td><td><code>MTE3_S</code></td><td>数据搬出到GM后，Scalar读取或修改该GM地址。</td></tr><tr><td>Scalar</td><td>Vector</td><td><code>SetValue</code></td><td>UB数据</td><td><code>S_V</code></td><td><code>SetValue</code>写入UB后，Vector读取该UB地址。</td></tr><tr><td>Scalar</td><td>Vector</td><td><code>GetValue</code></td><td>标量值</td><td>—</td><td><code>GetValue</code>返回值直接作为后续Vector指令参数，不需要插入<code>S_V</code>。</td></tr><tr><td>Scalar</td><td>MTE2</td><td><code>SetValue</code></td><td>GM数据</td><td><code>S_MTE2</code></td><td><code>SetValue</code>写入GM后，MTE2读取该GM地址作为搬运源。</td></tr><tr><td>Scalar</td><td>MTE3</td><td><code>SetValue</code></td><td>UB数据</td><td><code>S_MTE3</code></td><td><code>SetValue</code>写入UB后，MTE3读取该UB地址作为搬运源。</td></tr></tbody></table><p>其中，<code>S_V</code>、<code>S_MTE2</code>和<code>S_MTE3</code>用于保护Scalar对地址数据的写入；<code>MTE2_S</code>、<code>V_S</code>和<code>MTE3_S</code>用于保护其他流水对地址数据的写入。若Scalar操作只是通过<code>GetValue</code>产生一个供后续接口使用的标量值，则不属于这类地址数据依赖。实际使用时还需要根据接口访问的地址和读写方向确认同步事件，不能仅根据流水类型机械插入或删除同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// GetValue返回标量值后，Duplicate直接使用该标量参数。</span>
<span class="c1">// Duplicate不需要重新读取srcLocal中的数据，因此无需插入S_V同步。</span>
<span class="kt">float</span><span class="w"> </span><span class="n">inputVal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">.</span><span class="n">GetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Duplicate</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">inputVal</span><span class="p">,</span><span class="w"> </span><span class="n">srcDataSize</span><span class="p">);</span><span class="w"> </span>

<span class="c1">// SetValue修改UB中的数据，后续DataCopy需要读取该数据。</span>
<span class="c1">// 这里依赖的是UB存储结果，而不是Scalar返回值，因此需要S_MTE3同步。</span>
<span class="n">srcLocal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">);</span>
<span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">S_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventID2</span><span class="p">);</span>
<span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">S_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventID2</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcDataSize</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=s(t,[["render",d]]);export{S as __pageData,m as default};
